SELECT a.commentId, a.pid, a.lectureInfoId, a.usercode, a.status, a.commentTime, a.comImg , a.commentInfo ,b.`name`,b.post_code AS headImg
FROM yh_health_lecture_comment AS a INNER JOIN `yh_user_reginfo` AS b ON a.`usercode`=b.`user_code` LEFT JOIN `yh_wx_user` AS c ON a.`usercode`=c.`user_id`
WHERE ( a.lectureInfoId = #{lid} AND a.pid = 0 ) and a.`status`=#{status,jdbcType=TINYINT} order by a.commentTime desc limit #{curPage},#{pageSize}
